__NUXT_JSONP__("/ch/how-to-apply", {data:[{details:{slug:"ch",pageTitle:"您计划申请哪类签证？ | Mentor Language Institute",pageDescription:"请从以下选项选择您的签证种类",title:"您计划申请哪类签证？",image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa.jpg",category:[{title:"请从以下选项选择您的签证种类:",btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fvisa_btn-ch.png",link:"\u002Fch\u002Fhow-to-apply\u002Fstudent-visa-f1"},btn_others:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fothers_btn-ch.png",link:"\u002Fch\u002Fhow-to-apply\u002Fothers"}}],content:{subtitle:"任何問題?",description:["通常情况下，你需要学生签证才能在美国长期留学。 \u003Cbr \u002F\u003E 如果您不知道您是否需要签证，请与我们联系。","办公室有八国语言的工作人员。"],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-ch.jpg",link:"\u002Fch\u002Fcontact"}},dir:"\u002Fhow-to-apply",path:"\u002Fhow-to-apply\u002Fch",extension:".json",createdAt:"2026-10-22T16:31:29.624Z",updatedAt:"2025-05-26T12:06:27.789Z"}}],fetch:{},mutations:void 0});